package com.logouttimer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("logouttimer")
public interface LogoutTimerConfig extends Config
{
	@ConfigItem(
			keyName = "sessionLengthMinutes",
			name = "Session length (minutes)",
			description = "How long the server keeps you logged in before a forced logout.",
			position = 0
	)
	@Range(min = 1, max = 600)
	default int sessionLengthMinutes()
	{
		return 360; // 6 hours
	}

	@ConfigItem(
			keyName = "warningMinutesBefore",
			name = "Warn this many minutes before",
			description = "Show a warning this many minutes before the automatic logout. "
					+ "Set this low (or set Session length low) to test the plugin quickly "
					+ "instead of waiting a full session.",
			position = 1
	)
	@Range(min = 0, max = 360)
	default int warningMinutesBefore()
	{
		return 30;
	}

	@ConfigItem(
			keyName = "repeatWarning",
			name = "Repeat warning every minute",
			description = "After the first warning, keep reminding you every minute until logout.",
			position = 2
	)
	default boolean repeatWarning()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showOverlay",
			name = "Show countdown overlay",
			description = "Show an on-screen countdown to the forced logout.",
			position = 3
	)
	default boolean showOverlay()
	{
		return true;
	}
}

package com.logouttimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class LogoutTimerOverlay extends OverlayPanel
{
    private final LogoutTimerPlugin plugin;
    private final LogoutTimerConfig config;

    @Inject
    private LogoutTimerOverlay(LogoutTimerPlugin plugin, LogoutTimerConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Duration remaining = plugin.getRemaining();
        if (remaining == null || !config.showOverlay())
        {
            return null;
        }

        long h = remaining.toHours();
        long m = remaining.toMinutes() % 60;
        long s = remaining.toSeconds() % 60;

        boolean warning = remaining.toMinutes() < config.warningMinutesBefore();

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Logout Timer")
                .color(warning ? Color.ORANGE : Color.WHITE)
                .build());
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Time left:")
                .right(String.format("%02d:%02d:%02d", h, m, s))
                .rightColor(warning ? Color.ORANGE : Color.WHITE)
                .build());

        return super.render(graphics);
    }
}

package com.logouttimer;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
		name = "6 Hour Logout Timer",
		description = "Warns you before the game's automatic session logout kicks in",
		tags = {"logout", "timer", "notification", "afk", "session"}
)
public class LogoutTimerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private LogoutTimerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private LogoutTimerOverlay overlay;

	private Instant sessionStart;
	private boolean sessionActive;
	private boolean warningSent;
	private int lastMinuteAnnounced = -1;

	@Provides
	LogoutTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LogoutTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		if (config.showOverlay())
		{
			overlayManager.add(overlay);
		}

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			beginSession();
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		sessionActive = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOGGED_IN && !sessionActive)
		{
			beginSession();
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.CONNECTION_LOST)
		{
			sessionActive = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!sessionActive || sessionStart == null)
		{
			return;
		}

		Duration elapsed = Duration.between(sessionStart, Instant.now());
		Duration sessionLength = Duration.ofMinutes(config.sessionLengthMinutes());
		Duration remaining = sessionLength.minus(elapsed);
		Duration warnAt = Duration.ofMinutes(config.warningMinutesBefore());

		if (remaining.isNegative())
		{
			sessionActive = false;
			return;
		}

		if (remaining.compareTo(warnAt) <= 0)
		{
			int minutesRemaining = (int) Math.ceil(remaining.toSeconds() / 60.0);

			if (!warningSent)
			{
				notifier.notify(String.format(
						"Heads up: automatic logout in about %d minute%s.",
						minutesRemaining, minutesRemaining == 1 ? "" : "s"));
				warningSent = true;
				lastMinuteAnnounced = minutesRemaining;
			}
			else if (config.repeatWarning() && minutesRemaining != lastMinuteAnnounced)
			{
				notifier.notify(String.format(
						"Still logged in - automatic logout in about %d minute%s.",
						minutesRemaining, minutesRemaining == 1 ? "" : "s"));
				lastMinuteAnnounced = minutesRemaining;
			}
		}
	}

	private void beginSession()
	{
		sessionStart = Instant.now();
		sessionActive = true;
		warningSent = false;
		lastMinuteAnnounced = -1;
	}

	Duration getRemaining()
	{
		if (!sessionActive || sessionStart == null)
		{
			return null;
		}
		Duration elapsed = Duration.between(sessionStart, Instant.now());
		Duration remaining = Duration.ofMinutes(config.sessionLengthMinutes()).minus(elapsed);
		return remaining.isNegative() ? Duration.ZERO : remaining;
	}
}

package com.logouttimer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LogoutTimerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LogoutTimerPlugin.class);
		RuneLite.main(args);
	}
}
